    # TODO: JOIN siswa -> ikut_ekskul -> ekskul
    return []

solution.code:
def ekskul_siswa(db, nama):
    baris = db.execute("SELECT ekskul.nama FROM siswa JOIN ikut_ekskul ON ikut_ekskul.siswa_id = siswa.id JOIN ekskul ON ekskul.id = ikut_ekskul.ekskul_id WHERE siswa.nama = ? ORDER BY ekskul.nama", (nama,)).fetchall()
    return [b[0] for b in baris]

def pecah_hobi(baris):
    hasil = []
    for id_, nama, hobi in baris:
        for h in hobi.split(","):
            h = h.strip()
            if h:
                hasil.append((id_, nama, h))
    return hasil

