    # TODO: JOIN item_pesanan dengan produk lalu jumlahkan harga * qty
    return 0

solution.code:
def total_pesanan(db, pesanan_id):
    baris = db.execute("SELECT COALESCE(SUM(produk.harga * item_pesanan.qty), 0) FROM item_pesanan JOIN produk ON produk.id = item_pesanan.produk_id WHERE item_pesanan.pesanan_id = ?", (pesanan_id,)).fetchone()
    return baris[0]

